head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setScrollLeft]<br/>GridView 컴포넌트의 가로 스크롤 위치를 설정합니다.",
    "validation" : [
        "left(필수) 파라미터로 가로 스크롤 위치를 픽셀(px)로 설정합니다. (예: 0=왼쪽 끝, 100=100px)",
        "left(필수) 파라미터에 최대 너비 초과값 설정 시 최대값으로 적용됩니다.",
        "left(필수) 파라미터에 음수값 설정 시 0 으로 처리됩니다.",
        "setScrollLeft() 로 스크롤 이동 시 onscrollx 이벤트가 발생합니다.",
        "drawType 속성값(virtual/native)에 관계없이 setScrollLeft 가 동작합니다.",
    ]
}



scwin.gVar = { "scrollxFired" : false };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - 컬럼 폭 합(900px) > 그리드 너비(300px) 로 가로 스크롤 확보
//  - con_drawType(미설정/virtual/native) 값을 gridView drawType 에 적용 → @spec3(drawType 무관 동작) 값별 검증
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // con_drawType : 문자열 enum → getValue() (미설정이면 빈값 → 엔진 기본 virtual)
    let vDrawType = con_drawType.getValue();

    // 바인딩 DataList 생성 (col1~col6, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // 테스트 참고 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 컬럼 폭 합(900px) > 그리드 너비(300px) 로 가로 스크롤 존재 (현재 drawType=' + (vDrawType || '미설정(기본 virtual)') + ')\n[절차] con_drawType(미설정/virtual/native) 선택 후 (Target 재생성) -> par_left 값(0 / 100 / 99999(최대초과) / -50(음수)) 선택 후 (setScrollLeft) 클릭\n[확인] getScrollLeft 및 스크롤영역 scrollLeft 로 적용 위치 (100=100px, 99999=최대값 clamp, -50=0), onscrollx 발생, drawType 값(virtual/native)에 관계없이 동작"', '', 'label1');

    // target 생성 (6컬럼 × 150px = 900px, drawType 은 con 값 적용)
    await scwin.createGridView(vDrawType);
}



// 가로 스크롤 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [];
    for (var i = 1; i <= 6; i++) {
        rows.push({ col1: "A" + i, col2: "B" + i, col3: "C" + i, col4: "D" + i, col5: "E" + i, col6: "F" + i });
    }
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성 (가로 넘침 그리드, onscrollx 바인딩)
//  - vDrawType 이 빈값(미설정)이면 drawType 속성 미지정(엔진 기본 virtual)
scwin.createGridView = async function (vDrawType) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let drawTypeAttr = vDrawType ? ('drawType="' + vDrawType + '" ') : '';

    let s = '';
    s += '<w2:gridView ' + ns + ' checkAllType="false" id="" dataList="data:dlt_bind" ' + drawTypeAttr + 'style="width:300px;height:250px;" ev:onscrollx="scwin.target1_onscrollx">';
    s += '<w2:caption style="" id="caption1" value="setScrollLeft 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="150" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="column5" value="col5"></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="column6" value="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="150" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="col5" value=""></w2:column>';
    s += '<w2:column width="150" style="" inputType="text" id="col6" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// @spec1 : setScrollLeft() 로 스크롤 이동 시 onscrollx 발생
scwin.target1_onscrollx = function (e) {
    scwin.gVar.scrollxFired = true;
}



// setScrollLeft 호출 : par_left(필수) 값을 픽셀 위치로 설정 후 적용값 확인
//  - getScrollLeft() 및 가로 스크롤 영역(scrollX_right)의 scrollLeft 로 적용 위치 확인
//  - 최대초과값 → clamp(scrollWidth-clientWidth), 음수값 → 0
//  - onscrollx 발생 여부 확인 (@spec1), drawType 미설정 상태에서도 동작 (@spec3)
scwin.btn_setScrollLeft_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let vLeft = parseInt(par_left.getValue(), 10);

    // onscrollx 발생 감지 초기화
    scwin.gVar.scrollxFired = false;

    // 가로 스크롤 영역의 최대 스크롤 값 (동적 조회)
    let scrollArea = document.querySelector("div[id*='target1_scrollX_right']");
    let maxScroll = scrollArea ? (scrollArea.scrollWidth - scrollArea.clientWidth) : 0;

    // 메소드 실행
    target1.setScrollLeft(vLeft);

    setTimeout(function () {
        let scrollLeft = scrollArea ? scrollArea.scrollLeft : 0;

        bottom.setReturnValue("[설정값 left=" + vLeft + "] getScrollLeft()=" + target1.getScrollLeft() + " / 스크롤영역 scrollLeft=" + scrollLeft + "px (최대 " + maxScroll + "px)");
        bottom.setReturnValue("[onscrollx 발생 여부] " + scwin.gVar.scrollxFired);        
    }, 300);
}
